morse.watch("div.release", el => {
  const card = el.querySelector(".release__card") || el;
  const hide = el.classList.contains("release--pre")
    || el.classList.contains("release--yanked")
    || /pre-?release|yanked/i.test(card.textContent);
  el.classList.toggle("release--filtered-out", hide);
}, { live: true });
